// Node.js
const encoded = Buffer.from("Hello", "utf8").toString("base64");
console.log(encoded); // SGVsbG8=

// Browser, UTF-8 safe
const bytes = new TextEncoder().encode("Hello");
let binary = "";
for (const b of bytes) binary += String.fromCharCode(b);
console.log(btoa(binary)); // SGVsbG8=
